#!/usr/bin/env python3

"""
old yaml converter for testing.
"""

import os
import sys
import yaml

class NoAliasDumper(yaml.SafeDumper):
    # This make sure aliases are expanded/copied when dumping
    def ignore_aliases(self, data):
        return True

# special loader with duplicate key checking
class UniqueKeyLoader(yaml.SafeLoader):
    def construct_mapping(self, node, deep=False):
        mapping = {}
        for key_node, value_node in node.value:
            key = self.construct_object(key_node, deep=deep)
            if key in mapping:
                err_msg = "Duplicate key \"{}\" found in YAML. Values: \"{}\" and \"{}\"".format(key, mapping[key], value_node.value)
                raise ValueError(err_msg)
            if isinstance(node, yaml.nodes.MappingNode):
                self.flatten_mapping(node)
            mapping[key] = self.construct_object(value_node, deep=deep)
        return super().construct_mapping(node, deep)

if __name__ == "__main__":
    if not (2 <= len(sys.argv) <= 3):
        sys.stderr.write ("""
Usage: {} input.yaml [output.yaml]

""".format(os.path.basename(sys.argv[0])))
        exit(1)

    input_file = sys.argv[1]

    if len(sys.argv) == 3:
        output_file = sys.argv[2]
        if os.path.abspath(input_file) == os.path.abspath(output_file):
            sys.stderr.write ("""
Input/Output are the same file.
Please don't build in source tree, instead setup a separate build directory.

    cmake -B build
    make -C build

""")
            exit(1)
        out = open(output_file, "w")
    else:
        out = sys.stdout

    yaml.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, UniqueKeyLoader.construct_mapping)
    with open(input_file, "r") as f:
        doc = yaml.load(f, Loader=UniqueKeyLoader)

    out.write(yaml.dump(doc, indent=2, Dumper=NoAliasDumper))

import sys
import re

def process_file(filename):
    try:
        with open(filename, 'r') as file:
            lines = file.readlines()

        # This will store the new lines for the updated file content 
        new_lines = []
        paramid_count = 0
        node_pattern = re.compile(r'^[^\s]+:')  # Matches new nodes (lines starting without spaces followed by :)
        comment_pattern = re.compile(r'^\s*#')  # Matches lines that are comments (starting with # optionally preceded by spaces)

        for line in lines:
            # Ignore comment lines
            if comment_pattern.match(line):
                new_lines.append(line)
                continue

            # If a new node starts, reset the paramid_count
            if node_pattern.match(line):
                paramid_count = 0

            if 'ParamID:' in line:
                new_lines.append(f'      ParamID: {paramid_count}\n')  # 6 spaces before ParamID
                paramid_count += 1
            else:
                new_lines.append(line)

        # Write the updated content back to the file
        with open(filename, 'w') as file:
            file.writelines(new_lines)

        print(f"File '{filename}' has been processed successfully.")

    except FileNotFoundError:
        print(f"Error: File '{filename}' not found.")
    except IOError as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python script.py <filename>")
    else:
        process_file(sys.argv[1])

import yaml
import sys

def parse_yaml(ppf_file_name):
    with open(ppf_file_name, "r") as f:
        ppf = yaml.safe_load(f)
    return ppf

def create_busctl_cmds(ppf):
    idx = 0
    for section in ppf["Sections"]:
        for component in section["Components"]:
            for ig in component["InfoGroups"]:
                for il in ig["InfoList"]:                 
                    Service = il["DbusParams"]["Service"]
                    ObjectPath = il["DbusParams"]["ObjectPath"]
                    Interface = il["DbusParams"]["Interface"]
                    Property = il["DbusParams"]["Property"]
                    for param in component["Params"]:
                        ObjectPath = ObjectPath.replace(f'${param["name"]}', str(param["value"]))
                    print(f"echo -n '{idx} ' ; ", f"busctl get-property {Service} {ObjectPath} {Interface} {Property} ; ", "#", section["ID"], component["ID"], ig["ID"], il["ID"], il["ParamID"])
                    idx += 1

if __name__ == "__main__":
    ppf = parse_yaml(sys.argv[1])
    create_busctl_cmds(ppf)

# Makefile for fdrtool

# Directory where fdr_logs_schema exists
PROTO_DIR := ..
VPATH= $(PROTO_DIR)
CUSTOMER ?= 1

.PHONY: fdrtool clean

fdrtool: fdrtool.py

clean:
	@echo "Cleaning up..."
	rm -f fdrtool
	rm -f protoc_middleman fdr_logs_schema_pb2.py
	rm -f *.pyc
	rm -f check_fdr_telemetry_coverage.py
	rm -f telemetry_catalog.py
	rm -f data_validator.py
	rm -rf fdr_logs
	rm -rf fdr_logs_db
	rm -rf dist build fdrtool.egg-info
	rm -rf __pycache__
	rm -f warning.txt
	rm -f tc.log
	rm -f .customer_view


protoc_middleman: fdr_logs_schema.proto
	#protoc --proto_path=$(PROTO_DIR) --python_out=. $(PROTO_DIR)/fdr_logs_schema.proto
	protoc --proto_path=.. --python_out=. --experimental_allow_proto3_optional ../fdr_logs_schema.proto
	@touch protoc_middleman

fdrtool: fdrtool.py protoc_middleman
	@echo "Writing shortcut script fdrtool..."
	@echo '#! /bin/sh' > fdrtool
	@echo './fdrtool.py "$$@"' >> fdrtool
ifeq ($(CUSTOMER), 0)
	@cp ../tools/data_validation/check_fdr_telemetry_coverage.py .
	@cp ../tools/data_validation/telemetry_catalog.py .
	@cp ../tools/data_validation/data_validator.py .
	@echo "0" > .customer_view
else
	@echo "1" > .customer_view
	@gawk -i inplace 'NR < 33 || NR > 43' config.yaml
endif
	@chmod +x fdrtool

install: all
	@echo "Building fdrtool..."
	python3 setup.py sdist
	python3 setup.py bdist_wheel
	@cd dist

.PHONY: all clean install
